import React, { type CSSProperties } from 'react';
import { chakra, useToken, type SystemStyleObject } from '@chakra-ui/react';
import { useUiCopy } from 'app/hooks/useUiCopy';

type ZimmLogoProps = {
  variant?: 'inverse' | 'default';
  /** Plain inline style overrides — a single static value per property (e.g. the Storybook
   * CustomWidth story's maxWidth). Cannot express Chakra's responsive array shorthand
   * (['mobile', null, 'desktop']) — a raw DOM style attribute has no concept of breakpoints,
   * it can only ever hold one unconditional value. Use `sx` instead for anything
   * breakpoint-dependent. */
  style?: CSSProperties;
  /** Chakra style-prop overrides, resolved through Chakra's own responsive-array-aware css()
   * — the only way a caller-supplied width/height can actually vary by breakpoint (real media
   * queries), unlike `style` above. header/index.tsx's per-breakpoint logo sizing is why this
   * exists. */
  sx?: SystemStyleObject;
};

// §7 raise: alias/size/logo/max-width (327px) and alias/size/logo/height (39px) → foundation/sizes.ts (UI designer)
// px kept provisionally — SVG viewport dimensions confirmed by Figma node 1892:50472 / 1892:50474.
// Pending designer confirmation: scale with zoom (→ rem) or remain fixed (→ px, hairline exception).
const LOGO_MAX_WIDTH = '327px'; // provisional
const LOGO_HEIGHT = '39px'; // provisional

/**
 * Atom — Zimmermann wordmark. Mirrors zimm-logo contract.
 * Inlined because webpack svg-sprite-loader (server) + ignore-loader (client)
 * prevent <img src> from resolving an SVG import to a URL.
 */
export const ZimmLogo = ({ variant = 'default', style, sx }: ZimmLogoProps) => {
  // Resolved from the registered theme rather than a var() string: an SVG `fill`
  // attribute needs a concrete colour value, not a custom-property reference.
  const [inverseColour, defaultColour] = useToken('colors', ['text.inverse', 'text.default']);
  const fill = variant === 'inverse' ? inverseColour : defaultColour;
  const { t } = useUiCopy();
  return (
    <chakra.svg
      viewBox="0 0 631 74.5312"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-label={t('zimm_logo.assistive_msg.wordmark', 'Zimmermann')}
      role="img"
      style={style}
      sx={{
        display: 'block',
        width: '100%',
        maxWidth: LOGO_MAX_WIDTH,
        height: LOGO_HEIGHT,
        overflow: 'clip',
        ...sx,
      }}
    >
      <path
        d="M4.7064 7.67794H45.8272L0 74.5312H54.5873V69.0322H10.5808L10.6495 68.963C11.9893 66.9916 54.7247 4.66903 56.4424 2.21347H4.7064V7.71253V7.67794Z"
        fill={fill}
      />
      <path d="M67.9087 2.21347H62.103V74.5312H67.9087V2.21347Z" fill={fill} />
      <path
        d="M153.922 74.5312L138.188 0L113.763 59.7979L89.3375 0L73.5693 74.5312H79.3063L91.0208 17.9497L113.763 74.5312L136.504 17.9497L148.219 74.5312H153.922Z"
