  ErrorInCart: 'zimmcartbuttongroup--error-in-cart',
};

const browser = await chromium.launch();
const page = await browser.newPage();
const results = {};

for (const [name, id] of Object.entries(stories)) {
  await page.goto(`${BASE}?id=${id}&viewMode=story`, { waitUntil: 'networkidle' });
  await page.waitForSelector('button', { timeout: 5000 }).catch(() => {});
