  const names = [];
  for (const b of buttons) {
    names.push(await b.getAttribute('aria-label'));
  }
  const rootLocator = page.locator('#storybook-root > div').first();
  const box = await rootLocator.boundingBox();
  const disabledFlags = [];
  for (const b of buttons) {
    disabledFlags.push(await b.isDisabled());
  }
  results[name] = { count: buttons.length, ariaLabels: names, rootHeight: box?.height, disabledFlags };
  await page.screenshot({ path: `/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad/story-${name}.png` });
