// SFCC-11 plan step 5.1 (zimmCartButtonGroup's Apple Pay / Google Pay buttons): a Figma-fidelity
// gap found by the build's coordinator, not planned in advance — those two buttons are icon-only
// in Figma (the mark itself is the label) but ZimmButton's labelled render path always rendered
// `label` as visible text with no way to suppress it. `hideLabelVisually` closes that gap by
// swapping the visible span for Chakra's `VisuallyHidden` — the label stays a real DOM text node
// (aria-label above is already unconditional, so the accessible name never depended on this
// prop), it just isn't shown on screen.
describe('ZimmButton — hideLabelVisually', () => {
  test('label renders as an ordinary visible span when the prop is omitted — no behaviour change for any existing caller', () => {
    renderButton({ label: 'Save' });

    const label = screen.getByText('Save');
    expect(getComputedStyle(label).position).not.toBe('absolute');
  });

  test('label renders as an ordinary visible span when the prop is explicitly false', () => {
    renderButton({ label: 'Save', hideLabelVisually: false });

    const label = screen.getByText('Save');
    expect(getComputedStyle(label).position).not.toBe('absolute');
  });

  test('label text stays in the DOM and remains the accessible name, but is visually hidden when true', () => {
    renderButton({ label: 'Apple Pay', hideLabelVisually: true, iconLeading: <span>logo</span> });

    // aria-label is set unconditionally on ChakraButton regardless of this prop — getByRole
    // finding the button by that name proves the accessible name never depended on the visible
    // span at all.
    expect(screen.getByRole('button', { name: 'Apple Pay' })).toBeInTheDocument();

    // The label text node itself still exists in the DOM (screen readers can still reach it) —
    // it's rendered via Chakra's standard sr-only clip technique
    // (@chakra-ui/visually-hidden's visuallyHiddenStyle), not removed.
    const label = screen.getByText('Apple Pay');
    const computed = getComputedStyle(label);
    expect(computed.position).toBe('absolute');
    expect(computed.width).toBe('1px');
    expect(computed.height).toBe('1px');
    expect(computed.overflow).toBe('hidden');
  });

  test('does not affect the icon rendered alongside it', () => {
    renderButton({ label: 'Google Pay', hideLabelVisually: true, iconLeading: <span data-testid="mark">logo</span> });

    expect(screen.getByTestId('mark')).toBeInTheDocument();
  });
});

