// ─── hideLabelVisually ────────────────────────────────────────────────────────

/**
 * `hideLabelVisually` keeps the label as a real, readable DOM/accessibility-tree text node — and
 * therefore the button's accessible name — while removing it from the visible render, for a
 * button whose real design is icon-only but still needs a genuine accessible name rather than an
 * empty one. `zimmCartButtonGroup`'s Apple Pay / Google Pay buttons are the reference consumer
 * (SFCC-11 plan step 5.1): a wordmark logo fills the visible slot via `iconLeading`, and this prop
 * keeps "Apple Pay"/"Google Pay" as the accessible name without a second, redundant caption
 * rendering next to the logo. `play` proves the accessible name still resolves even though no
 * label text is visible on screen — the interesting thing this story exists to show can't be seen
 * in a screenshot alone.
 */
export const HiddenLabel: Story = {
  name: 'Secondary — Hidden Label (icon-only, real accessible name)',
  args: {
    variant: 'secondary',
    label: 'Add to Bag',
    size: 'large',
    hideLabelVisually: true,
    iconLeading: <ZimmIcon type="bag" size="md" aria-hidden={true} />,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole('button', { name: 'Add to Bag' })).toBeInTheDocument();
    // The visible text node still exists in the DOM (screen readers can reach it) — it's
    // rendered via Chakra's VisuallyHidden clip technique, not removed outright.
    await expect(canvas.getByText('Add to Bag')).toBeInTheDocument();
  },
};

// ─── style prop samples ──────────────────────────────────────────────────────

